import{_ as t,o as e,c as i,a5 as o}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"Plan — G7 Subscription & Billing (Mobile, READ-ONLY)","description":"","frontmatter":{},"headers":[],"relativePath":"mobile/features/g7-subscription-billing/plan.md","filePath":"mobile/features/g7-subscription-billing/plan.md"}'),c={name:"mobile/features/g7-subscription-billing/plan.md"};function a(l,n,h,r,s,d){return e(),i("div",null,[...n[0]||(n[0]=[o('<h1 id="plan-—-g7-subscription-billing-mobile-read-only" tabindex="-1">Plan — G7 Subscription &amp; Billing (Mobile, READ-ONLY) <a class="header-anchor" href="#plan-—-g7-subscription-billing-mobile-read-only" aria-label="Permalink to &quot;Plan — G7 Subscription &amp; Billing (Mobile, READ-ONLY)&quot;">​</a></h1><p>&gt; <a href="./spec.html">spec.md</a> — chi tiết API/flows/business rules đầy đủ. File này là bản tóm tắt thứ tự implement + quyết định kỹ thuật chốt.</p><h2 id="thu-tu-implement-theo-dependency" tabindex="-1">Thứ tự implement (theo dependency) <a class="header-anchor" href="#thu-tu-implement-theo-dependency" aria-label="Permalink to &quot;Thứ tự implement (theo dependency)&quot;">​</a></h2><ol><li><strong>Chặn trước khi code bất kỳ màn nào</strong> — cần xác nhận với BE/PM: <ul><li>Route plan chính thức: hệ cũ <code>SubscriptionController</code> (User-scoped) hay hệ mới <code>BillingPlanController</code>/<code>BillingController</code> (Agency-scoped).</li><li>Route invoice chính thức: <code>/billing/transactions</code> hay <code>/billing/agencies/{id}/invoices</code>.</li><li>Hướng &quot;không thanh toán thật trong app, chỉ mở web ngoài&quot; — đây là <strong>đề xuất của spec, chưa phải quyết định chính thức</strong>, cần PM duyệt.</li></ul></li><li><strong>Current Plan screen</strong> — đơn giản nhất, chỉ đọc.</li><li><strong>Plan comparison list</strong> — nút &quot;Nâng cấp&quot; mở web ngoài (<code>Linking.openURL</code>), không checkout trong app.</li><li><strong>Invoice history</strong> — list + detail + tải receipt.</li></ol><h2 id="quyet-đinh-ky-thuat-đa-chot" tabindex="-1">Quyết định kỹ thuật đã chốt <a class="header-anchor" href="#quyet-đinh-ky-thuat-đa-chot" aria-label="Permalink to &quot;Quyết định kỹ thuật đã chốt&quot;">​</a></h2><ul><li><strong>G7 là READ-ONLY tuyệt đối</strong> — không build bất kỳ luồng mua/upgrade/thanh toán thật trong app. Lý do: Apple App Store Review Guidelines (mục 3.1.1) yêu cầu nội dung số bán trong app dùng IAP nếu app public; flow SePay QR hiện tại là thanh toán ngoài hệ sinh thái Apple/Google.</li><li><strong>Vì bản demo nội bộ (Expo Go/TestFlight/ad-hoc, không public App Store)</strong>, rủi ro chính sách này KHÔNG chặn demo capstone — nhưng để tránh viết lại UI khi/nếu app public hoá sau, vẫn giữ nguyên tắc READ-ONLY ngay từ đầu.</li><li><strong>Payment gateway thật là SePay (QR chuyển khoản ngân hàng), KHÔNG phải PayOS</strong> như BA doc ghi — xác nhận bằng code thật (<code>SePayProperties</code>, <code>SePayTransactionClient</code>, <code>qrUrl</code> trong <code>AgencyPaymentPanel.tsx</code>). Không hiển thị nhầm tên gateway trong UI.</li><li><strong>AI credit 2 lớp</strong>: hạn mức Agency (từ plan) và hạn mức Creator (Owner set, hard limit — hết credit chặn hẳn, không phải soft warning).</li></ul><h2 id="viec-can-xac-nhan-truoc-khi-code-chua-lam-xem-spec-muc-8" tabindex="-1">Việc cần xác nhận trước khi code (chưa làm, xem spec mục 8) <a class="header-anchor" href="#viec-can-xac-nhan-truoc-khi-code-chua-lam-xem-spec-muc-8" aria-label="Permalink to &quot;Việc cần xác nhận trước khi code (chưa làm, xem spec mục 8)&quot;">​</a></h2><ul><li>2 hệ plan song song — xác nhận route web đang dùng thật trước khi mobile tích hợp.</li><li><code>/billing/transactions</code> vs <code>/billing/agencies/{id}/invoices</code> trùng chức năng — xác nhận route active, tránh build trên route deprecated.</li><li>Khuyến nghị &quot;mở web ngoài&quot; chưa phải quyết định chính thức — PM cần duyệt.</li><li>Số liệu giá/credit mỗi plan nằm trong seed/migration (<code>AdminDemoSeeder.java</code>), không đọc được trực tiếp từ code Java — cần tra thêm nếu muốn demo UI với số liệu thật.</li></ul><h2 id="rui-ro-con-mo" tabindex="-1">Rủi ro còn mở <a class="header-anchor" href="#rui-ro-con-mo" aria-label="Permalink to &quot;Rủi ro còn mở&quot;">​</a></h2><ul><li>BA doc ghi PayOS nhưng code dùng SePay — cần BA/PM xác nhận doc chưa update hay đổi gateway giữa đường, tránh gây hiểu lầm khi review tài liệu.</li></ul>',10)])])}const p=t(c,[["render",a]]);export{g as __pageData,p as default};
